def link_lines_for_tasks_already_linked(apps, schema_editor):
    """Requests linked before this showed their key in the "Planned" line, which now leaves it
    to its own line: give them that line, at the moment they were planned."""
    Request = apps.get_model("requests", "Request")
    StatusEvent = apps.get_model("requests", "StatusEvent")
    TaskEvent = apps.get_model("requests", "TaskEvent")
    for request in Request.objects.exclude(jira_key=""):
        planned = (
            StatusEvent.objects.filter(request=request, to_status="planned")
            .order_by("created_at")
            .first()
        )
        event = TaskEvent.objects.create(
            request=request,
            kind="linked",
            task_key=request.jira_key,
            actor=planned.actor if planned else None,
        )
        if planned:
            # auto_now_add set "now"; the line belongs where the task was linked.
            TaskEvent.objects.filter(pk=event.pk).update(created_at=planned.created_at)


